function removeResponse(n){n.preventDefault();const i=n.target;let r=i.getAttribute("data-container"),u=document.getElementById(r);const f=n.target.parentElement;u.removeChild(f);const t=document.getElementsByClassName("remove-multiple-answer");t.length==1&&t[0].remove()}function addDuplicateField(n){n.preventDefault();const e=n.target.getAttribute("data-container"),u=document.getElementById(e),o=u.firstElementChild,i=o.cloneNode(!0),r=Date.now(),t=i.querySelector("input[type='text']"),f=i.querySelector("ul");t.value="";t.id=`${t.id}-${r}`;t.setAttribute("data-suggestions-id",`autocomplete-suggestions-${r}`);t.oninput=n=>filterSuggestions(n,r);f&&(f.id=`autocomplete-suggestions-${r}`);u.appendChild(i);attachRemoveResponseButton(i)}function filterSuggestions(n,t){const i=n.target,r=i.value.toLowerCase(),u=document.getElementById(`autocomplete-suggestions-${t}`);if(u.innerHTML="",r.length>0){const n=countries.filter(n=>n.toLowerCase().includes(r));n.forEach(n=>{const r=document.createElement("li");r.textContent=n;r.classList.add("autocomplete-suggestion");r.onclick=()=>selectSuggestion(n,i,`autocomplete-suggestions-${t}`);u.appendChild(r)})}}function selectSuggestion(n,t,i){t.value=n;document.getElementById(i).innerHTML=""}const addResponseButtons=document.querySelectorAll(".add-another-answer");addResponseButtons.length>0&&addResponseButtons.forEach(function(n){n.addEventListener("click",addDuplicateField)});const removeResponseButtons=document.querySelectorAll(".remove-multiple-answer");removeResponseButtons.length>0&&removeResponseButtons.forEach(function(n){n.addEventListener("click",removeResponse)});const conditionalCheckboxes=document.querySelectorAll(".controlling-conditional");conditionalCheckboxes&&conditionalCheckboxes.length>0&&conditionalCheckboxes.forEach(function(n){const t=n.id+"-supplementary",i=document.getElementById(t);n.checked&&i.removeAttribute("disabled");n.addEventListener("change",function(){const i=n.id+"-supplementary",t=document.getElementById(i);n.checked?t.removeAttribute("disabled"):t.setAttribute("disabled","disabled")})});document.getElementById("save-and-return").addEventListener("click",function(){document.getElementById("show-next-question").value="false";document.querySelector("form").submit()});